const meridiemMatch = (input, isLowerCase) => {
  let isAfternoon
  const { meridiem } = locale
  if (!meridiem) {
    isAfternoon = input === (isLowerCase ? 'pm' : 'PM')
  } else {
    for (let i = 1; i <= 24; i += 1) {
      // todo: fix input timezone
      const m = meridiem(i, 0, isLowerCase)
      if (m && input === m) {
        isAfternoon = i > 12
        break
      }
    }
  }
  return isAfternoon
}
```

