import dayjs from '../../src'
import customParseFormat from '../../src/plugin/customParseFormat'
import '../../src/locale/zh-cn'

dayjs.extend(customParseFormat)

it('meridiem locale AM', () => {
  const f = 'YYYY-MM-DD A hh:mm'
  console.log(dayjs('2018-05-02 上午 10:00', f, 'zh-cn').format('YYYY-MM-DD HH:mm'))
  console.log(dayjs('2018-05-02 凌晨 1:00', f, 'zh-cn').format('YYYY-MM-DD HH:mm'))
  console.log(dayjs('2018-05-02 早上 8:00', f, 'zh-cn').format('YYYY-MM-DD HH:mm'))
  expect(dayjs('2018-05-02 上午 10:00', f, 'zh-cn').format('YYYY-MM-DD HH:mm')).toBe('2018-05-02 10:00')
  expect(dayjs('2018-05-02 凌晨 1:00', f, 'zh-cn').format('YYYY-MM-DD HH:mm')).toBe('2018-05-02 01:00')
  expect(dayjs('2018-05-02 早上 8:00', f, 'zh-cn').format('YYYY-MM-DD HH:mm')).toBe('2018-05-02 08:00')
})

it('meridiem locale PM', () => {
  const f = 'YYYY-MM-DD A hh:mm'
  console.log(dayjs('2018-05-02 下午 10:00', f, 'zh-cn').format('YYYY-MM-DD HH:mm'))
  console.log(dayjs('2018-05-02 晚上 11:00', f, 'zh-cn').format('YYYY-MM-DD HH:mm'))
  expect(dayjs('2018-05-02 下午 10:00', f, 'zh-cn').format('YYYY-MM-DD HH:mm')).toBe('2018-05-02 22:00')
  expect(dayjs('2018-05-02 晚上 11:00', f, 'zh-cn').format('YYYY-MM-DD HH:mm')).toBe('2018-05-02 23:00')
})

it('still parses default AM/PM', () => {
  expect(dayjs('2018-05-02 01:02:03.004 AM +01:00', 'YYYY-MM-DD HH:mm:ss.SSS A Z').valueOf()).toBe(1525226523004)
  expect(dayjs('2018-05-02 12:00 am', 'YYYY-MM-DD hh:mm a').format('HH:mm')).toBe('00:00')
  expect(dayjs('2018-05-02 12:00 pm', 'YYYY-MM-DD hh:mm a').format('HH:mm')).toBe('12:00')
})
```
